package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.nio.file.Path;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import java.util.function.Function;

/** Current revision owns management authority; retained sessions own pending OAuth state. */
public final class ProviderDiscoveryService implements AutoCloseable {
    public interface Session extends AutoCloseable {JsonNode providers();JsonNode authMethods();JsonNode authorize(String provider,int method);boolean completeOauth(String provider,int method,String code);void close();}
    @FunctionalInterface public interface SessionFactory {Session start(JsonNode cli,Map<String,String> environment);}
    private record Flow(ObjectNode view,Session session){}
    private static final class LockEntry {final ReentrantLock lock=new ReentrantLock();int users;}
    private final Function<String,ObjectNode> revisions;private final Map<String,String> environment;private final ModelDiscoveryService discovery;private final SessionFactory sessions;
    private final Map<String,Flow> flows=new LinkedHashMap<>();private final Map<String,LockEntry> locks=new HashMap<>();private final ScheduledExecutorService expiry;private volatile boolean closed;
    public ProviderDiscoveryService(RuntimeConnectionService connections){this(connections,System.getenv());}
    public ProviderDiscoveryService(RuntimeConnectionService connections,Map<String,String> env){this(connections::claimRevision,env,OpenCodeManagementSession::start);}
    public ProviderDiscoveryService(Function<String,ObjectNode> revisions,Map<String,String> env,SessionFactory sessions){this.revisions=revisions;this.environment=Map.copyOf(env);this.discovery=new ModelDiscoveryService(env);this.sessions=sessions;expiry=java.util.concurrent.Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"tenvyr-oauth-expiry");t.setDaemon(true);return t;});expiry.scheduleAtFixedRate(this::expire,1,1,TimeUnit.SECONDS);}
    private <T>T locked(String key,java.util.function.Supplier<T> work){LockEntry entry;synchronized(locks){entry=locks.get(key);if(entry==null){if(locks.size()>=1024)throw fail("AUTH_FLOW_LIMIT","Too many pending auth operations");entry=new LockEntry();locks.put(key,entry);}entry.users++;}entry.lock.lock();try{if(closed)throw fail("OPENCODE_SERVER_FAILED","Provider discovery is closed");return work.get();}finally{entry.lock.unlock();synchronized(locks){if(--entry.users==0)locks.remove(key,entry);}}}
    private ObjectNode revision(String id){return revisions.apply(id);}
    private static JsonNode cli(JsonNode revision){if(!revision.path("profile").path("cli").isObject())throw fail("RUNTIME_NOT_SUPPORTED","Connection has no CLI profile");return revision.path("profile").path("cli");}
    private static void requireOpenCode(JsonNode revision){if(!Json.text(revision.path("profile"),"runtimeKind").equals("opencode"))throw fail("RUNTIME_NOT_SUPPORTED","Provider management requires OpenCode");}
    private ObjectNode envelope(String id,JsonNode revision){return Json.object("connectionId",id,"revisionNumber",revision.get("revisionNumber"),"runtimeKind",revision.path("profile").get("runtimeKind"));}
    public ObjectNode discoverRuntimeProviders(String id){ObjectNode r=revision(id),out=envelope(id,r);ArrayNode providers=Json.array();if(Json.text(r.path("profile"),"runtimeKind").equals("opencode")){try(Session session=sessions.start(cli(r),environment)){JsonNode list=OpenCodeManagementSession.parseProviderList(session.providers());Set<String> connected=new HashSet<>();list.path("connected").forEach(n->connected.add(n.asText()));Set<String> seen=new HashSet<>();for(JsonNode item:list.path("all")){String p=Json.text(item,"id");seen.add(p);providers.add(Json.object("providerId",p,"authenticated",connected.contains(p),"loginCommand","opencode auth login --provider "+p));}for(String p:connected)if(seen.add(p))providers.add(Json.object("providerId",p,"authenticated",true,"loginCommand","opencode auth login --provider "+p));}}out.set("providers",providers);return out;}
    public ObjectNode refreshRuntimeModels(String id,String provider){if(provider!=null)OpenCodeManagementSession.providerId(provider);ObjectNode r=revision(id),out=envelope(id,r);String kind=Json.text(r.path("profile"),"runtimeKind");ArrayNode models=Json.array();if(r.path("profile").has("cli")){if(kind.equals("opencode"))models=discovery.discoverOpenCodeModels(cli(r),provider);else if(kind.equals("codex"))models=discovery.discoverCodexModels(cli(r));}out.set("catalog",Json.object("sourceId",id,"discoveredAt",Instant.now().toString(),"models",models));return out;}
    public ObjectNode getRuntimeProviderAuthMethods(String id,String provider){OpenCodeManagementSession.providerId(provider);ObjectNode r=revision(id),out=envelope(id,r);JsonNode methods=Json.array();if(Json.text(r.path("profile"),"runtimeKind").equals("opencode")){try(Session session=sessions.start(cli(r),environment)){methods=OpenCodeManagementSession.parseAuthMethods(session.authMethods()).path(provider);if(!methods.isArray())methods=Json.array();}}out.put("providerId",provider);out.set("methods",methods);return out;}
    public ObjectNode beginAuthFlow(JsonNode input){String id=Json.text(input,"connectionId"),provider=OpenCodeManagementSession.providerId(Json.text(input,"providerId"));int index=Json.integer(input,"methodIndex",-1);if(!input.path("methodIndex").isIntegralNumber()||index<0||index>32)throw fail("INVALID_METHOD_INDEX","Invalid method index");return locked(id+"#"+provider,()->{ObjectNode r=revision(id);requireOpenCode(r);int rev=Json.integer(r,"revisionNumber",0);evict(id,provider,rev);synchronized(flows){for(Flow f:flows.values())if(Json.text(f.view,"connectionId").equals(id)&&Json.text(f.view,"providerId").equals(provider)){if(Json.integer(f.view,"methodIndex",-1)!=index||input.has("expectedMethodType")&&!Objects.equals(input.get("expectedMethodType"),f.view.get("methodType"))||input.has("expectedMethodLabel")&&!Objects.equals(input.get("expectedMethodLabel"),f.view.get("methodLabel")))throw fail("AUTH_FLOW_CONFLICT","A different auth method already owns this target");return beginView(f.view,true);}if(flows.size()>=64)throw fail("AUTH_FLOW_LIMIT","Too many active auth flows");}Session session=sessions.start(cli(r),environment);boolean retained=false;try{JsonNode methods=OpenCodeManagementSession.parseAuthMethods(session.authMethods()).path(provider),method=null;for(JsonNode m:methods)if(Json.integer(m,"methodIndex",-1)==index){method=m;break;}if(method==null)throw fail("INVALID_METHOD_INDEX","Selected auth method is missing");if(input.has("expectedMethodType")&&!input.get("expectedMethodType").equals(method.get("type"))||input.has("expectedMethodLabel")&&!input.get("expectedMethodLabel").equals(method.get("label")))throw fail("AUTH_METHOD_INVALID","Selected auth method changed; select it again");if(Json.bool(method,"requiresPrompt",false))throw fail("AUTH_METHOD_UNSUPPORTED","Auth method requires runtime-owned prompt inputs");if(!Json.text(method,"type").equals("oauth"))throw fail("AUTH_METHOD_NOT_OAUTH","Use the official runtime login command for this method");ObjectNode auth=OpenCodeManagementSession.parseAuthorization(session.authorize(provider,index));ObjectNode current=revision(id);if(Json.integer(current,"revisionNumber",0)!=rev)throw fail("AUTH_FLOW_STALE","Connection changed during authorization");ObjectNode view=Json.object("authFlowId",UUID.randomUUID().toString().replace("-",""),"connectionId",id,"connectionRevision",rev,"providerId",provider,"methodIndex",index,"methodType",method.get("type"),"methodLabel",method.get("label"),"url",auth.get("url"),"authorizationMethod",auth.get("method"),"instructions",auth.get("instructions"),"expiresAt",System.currentTimeMillis()+600000);synchronized(flows){if(closed||flows.size()>=64)throw fail("AUTH_FLOW_LIMIT","Auth flow capacity is unavailable");flows.put(Json.text(view,"authFlowId"),new Flow(view,session));}retained=true;return beginView(view,false);}finally{if(!retained)session.close();}});}
    private static ObjectNode beginView(ObjectNode v,boolean resumed){return Json.object("authFlowId",v.get("authFlowId"),"url",v.get("url"),"method",v.get("authorizationMethod"),"instructions",v.get("instructions"),"connectionId",v.get("connectionId"),"connectionRevision",v.get("connectionRevision"),"providerId",v.get("providerId"),"resumed",resumed);}
    public ArrayNode getActiveAuthFlows(String id,String provider){expire();List<Flow> candidate;synchronized(flows){candidate=flows.values().stream().filter(f->Json.text(f.view,"connectionId").equals(id)&&(provider==null||Json.text(f.view,"providerId").equals(provider))).toList();}ArrayNode result=Json.array();if(candidate.isEmpty())return result;ObjectNode r;try{r=revision(id);}catch(RuntimeFailure e){if(!Set.of("CONNECTION_NOT_FOUND","CONNECTION_REVOKED").contains(e.code()))throw e;candidate.forEach(f->cancelAuthFlow(Json.text(f.view,"authFlowId")));return result;}for(Flow flow:candidate){if(Json.integer(flow.view,"connectionRevision",0)!=Json.integer(r,"revisionNumber",0))cancelAuthFlow(Json.text(flow.view,"authFlowId"));else result.add(flow.view.deepCopy());}return result;}
    public ObjectNode completeAuthFlow(String flowId,String code){Flow peek;synchronized(flows){peek=flows.get(flowId);}if(peek==null)throw fail("AUTH_FLOW_NOT_FOUND","Auth flow is missing or expired");return locked(Json.text(peek.view,"connectionId")+"#"+Json.text(peek.view,"providerId"),()->{Flow flow;synchronized(flows){flow=flows.remove(flowId);}if(flow==null)throw fail("AUTH_FLOW_NOT_FOUND","Auth flow is missing or expired");try{if(Json.longValue(flow.view,"expiresAt",0)<=System.currentTimeMillis())throw fail("AUTH_FLOW_EXPIRED","Auth flow expired");ObjectNode current=revision(Json.text(flow.view,"connectionId"));if(Json.integer(current,"revisionNumber",0)!=Json.integer(flow.view,"connectionRevision",0))throw fail("AUTH_FLOW_STALE","Connection changed during authentication");if(code!=null&&(code.length()>1024||!code.matches("[A-Za-z0-9._~+/=-]+")))throw fail("AUTH_CODE_INVALID","Authorization code is out of bounds");if(Json.text(flow.view,"authorizationMethod").equals("code")&&(code==null||code.isBlank()))throw fail("AUTH_CODE_REQUIRED","Authorization code is required");boolean connected=false;try{if(flow.session.completeOauth(Json.text(flow.view,"providerId"),Json.integer(flow.view,"methodIndex",0),code)){for(JsonNode p:OpenCodeManagementSession.parseProviderList(flow.session.providers()).path("connected"))if(p.asText().equals(Json.text(flow.view,"providerId")))connected=true;}}catch(RuntimeFailure e){connected=false;}ObjectNode after=revision(Json.text(flow.view,"connectionId"));if(Json.integer(after,"revisionNumber",0)!=Json.integer(flow.view,"connectionRevision",0))throw fail("AUTH_FLOW_STALE","Connection changed during callback");return Json.object("connected",connected,"providerId",flow.view.get("providerId"),"connectionId",flow.view.get("connectionId"));}finally{flow.session.close();}});}
    public boolean cancelAuthFlow(String id){Flow flow;synchronized(flows){flow=flows.remove(id);}if(flow!=null)flow.session.close();return flow!=null;}
    private void evict(String id,String provider,int revision){List<String> stale;synchronized(flows){stale=flows.entrySet().stream().filter(e->Json.text(e.getValue().view,"connectionId").equals(id)&&Json.text(e.getValue().view,"providerId").equals(provider)&&Json.integer(e.getValue().view,"connectionRevision",0)!=revision).map(Map.Entry::getKey).toList();}stale.forEach(this::cancelAuthFlow);}
    private void expire(){List<String> stale;synchronized(flows){stale=flows.entrySet().stream().filter(e->Json.longValue(e.getValue().view,"expiresAt",0)<=System.currentTimeMillis()).map(Map.Entry::getKey).toList();}stale.forEach(this::cancelAuthFlow);}
    public ObjectNode testRuntimeTarget(String id,String model){ObjectNode r=revision(id);JsonNode cli=cli(r);String kind=Json.text(r.path("profile"),"runtimeKind");if(!RuntimeProfiles.KINDS.contains(kind))throw fail("RUNTIME_NOT_SUPPORTED","Target testing requires a supported runtime");if(model!=null&&!ModelDiscoveryService.isBoundedModelId(model))throw fail("INVALID_MODEL_ID","Invalid requested model");if(model!=null&&kind.equals("opencode")){String provider=model.contains("/")?model.substring(0,model.indexOf('/')):null;if(provider==null)throw fail("PROVIDER_NOT_AUTHENTICATED","Explicit OpenCode model requires a provider prefix");boolean ready=false;for(JsonNode p:discoverRuntimeProviders(id).path("providers"))if(Json.text(p,"providerId").equals(provider)&&Json.bool(p,"authenticated",false))ready=true;if(!ready)throw fail("PROVIDER_NOT_AUTHENTICATED","Requested provider is not authenticated");ObjectNode fresh=revision(id);if(!fresh.get("revisionNumber").equals(r.get("revisionNumber")))throw fail("AUTH_FLOW_STALE","Connection changed during target validation");}List<String> args=new ArrayList<>(ProcessBoundary.args(cli.path("args")));if(model!=null){JsonNode prefix=cli.has("modelArgvPrefix")?cli.get("modelArgvPrefix"):RuntimeProfiles.template(kind).get("modelArgvPrefix");args.addAll(ProcessBoundary.args(prefix));args.add(model);}boolean stdin=cli.path("args").toString().contains("\"-\"");if(!stdin)args.add("Respond with exactly: OK");ProcessBoundary.Result result=ProcessBoundary.run(Json.text(cli,"command"),args,cli.has("cwd")?Path.of(Json.text(cli,"cwd")):null,ProcessBoundary.environment(cli,environment,true),30000,65536,stdin?"Respond with exactly: OK":null);return Json.object("connectionId",id,"revisionNumber",r.get("revisionNumber"),"runtimeKind",kind,"requestedModelId",model,"status",ModelDiscoveryService.ok(result)?"ok":"failed","exitCode",result.status(),"durationMs",result.durationMs(),"outputTruncated",result.exceeded());}
    public void close(){closed=true;expiry.shutdownNow();List<String> ids;synchronized(flows){ids=new ArrayList<>(flows.keySet());}ids.forEach(this::cancelAuthFlow);}
    private static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
